Test.Text:
create procedure CK.sTest
as 
begin
  insert into CK.tTable( X, Y, Z )
    /*before*/select 1, /* comment inside*/2, 3/*after*/;
  update CK.tTable set X = 8, Y = 7 where Z !< 9 and T = 4;
  select * from CK.tTable;
end

Test.Description:
create transformer on CK.sTest
as
begin
  replace first range {select 1, 2, 3} with "select 4, 5, 6";
  replace first range {Z>=9} with "Z = 9000";
  replace first range {T=4} with "T = 4000";
end

Test.ResultText:
create procedure CK.sTest
as  
begin
  insert into CK.tTable( X, Y, Z )
    /*before*/select 4, 5, 6/*after*/;
  update CK.tTable set X = 8, Y = 7 where Z = 9000 and T = 4000;
  select * from CK.tTable;
end

